"description":"Dirección, horarios y mapa.","enabled":true},{"id":"mod-cta","key":"finalCta","label":"CTA final","description":"Bloque oscuro de WhatsApp al cierre.","enabled":true}]},"analytics":{"googleAnalyticsId":"","googleTagManagerId":"","notes":"Pega aquí el ID de medición (G-XXXXXXXX) o el contenedor GTM (GTM-XXXX)."}}'::jsonb)
